#if SIZEOF_LONG  == 4

uint32_t __div64_32(uint64_t *n, uint32_t base)

{

    uint64_t rem = *n;

    uint64_t b = base;

    uint64_t res, d = 1;

    uint32_t high = rem >> 32;



    /* Reduce the thing a bit first */

    res = 0;

    if (high >= base) {

        high /= base;

        res = (uint64_t) high << 32;

        rem -= (uint64_t) (high*base) << 32;

    }



    while ((int64_t)b > 0 && b < rem) {

        b = b+b;

        d = d+d;

    }



    do {

        if (rem >= b) {

            rem -= b;

            res += d;

        }

        b >>= 1;

        d >>= 1;

    } while (d);



    *n = res;

    return rem;

}

#endif /* SIZEOF_LONG  == 4 */



/**

 * Implementation of rand_r that is consistent across all platforms

 * This algorithm is mentioned in the ISO C standard, here extended

 * for 32 bits.

 * @param: seed

 * @return: random number

 */

uint32_t tcpr_random(uint32_t *seed)

{

  unsigned int next = *seed;

  int result;



  next *= 1103515245;

  next += 12345;

  result = (unsigned int) (next / 65536) % 2048;



  next *= 1103515245;

  next += 12345;

  result <<= 10;

  result ^= (unsigned int) (next / 65536) % 1024;



  next *= 1103515245;

  next += 12345;

  result <<= 10;

  result ^= (unsigned int) (next / 65536) % 1024;



  *seed = next;



  return result;

}



/**

 * #416 - Ensure STDIN is not left in non-blocking mode after closing

 * a program. BSD and Unix derivatives should utilize `FIONBIO` due to known

 * issues with reading from tty with a 0 byte read returning -1 opposed to 0.

 */

void restore_stdin(void)

{

#ifdef FIONBIO

    int nb = 0;



    ioctl(0, FIONBIO, &nb);

#else

    fcntl(0, F_SETFL, fcntl(0, F_GETFL) | O_NONBLOCK);

#endif /* FIONBIO */

}

